changeSet.sql:
DO $contact_version$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'clinlims'
            AND table_name = 'patient_contact' AND column_name = 'lastupdated' AND data_type = 'date') THEN
        ALTER TABLE clinlims.patient_contact ALTER COLUMN lastupdated TYPE timestamp without time zone
            USING lastupdated::timestamp without time zone;
    END IF;
END
$contact_version$;
